<?php require 'vendor/autoload.php'; $app = require_once 'bootstrap/app.php'; $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); $order = App\Models\Order::first(); if ($order) { try { $service = app(App\Services\OrderService::class); $service->updateOrderStatus($order->id, 'completed'); echo 'Sukses'; } catch (\Exception $e) { echo 'Error: ' . $e->getMessage(); } }
